<script setup lang="ts">
import { computed } from 'vue'
import { api, time } from '../lib/api'
import { selectedDate, user, isParent, isAdmin } from '../lib/state'
import { useResource } from '../lib/ui'
import type { Dashboard } from '../lib/types'
import AppIcon from '../components/AppIcon.vue'
import StudentAvatar from '../components/StudentAvatar.vue'
import LoadState from '../components/LoadState.vue'
import StatusBadge from '../components/StatusBadge.vue'
const {data,loading,error,refresh} = useResource(() => api<Dashboard>(`/dashboard?date=${selectedDate.value}`), [selectedDate])
const percent = (a: number, b: number) => b ? Math.round(a / b * 100) : 0
const done = computed(() => percent(data.value?.completedHomeworkCount || 0, data.value?.homeworkCount || 0))
const attendanceRate = computed(() => percent(data.value?.presentCount || 0,data.value?.studentCount || 0))
const greeting = computed(() => { const hour = new Date().getHours(); return hour < 12 ? '上午好' : hour < 18 ? '下午好' : '晚上好' })
const activityTarget = (activity: { type: string; id: number }) => {
  const map: Record<string, string> = { HOMEWORK_COMPLETED: '/homework', MISTAKE_MASTERED: '/mistakes', FITNESS: '/fitness', DEMO: '/attendance' }
  return map[activity.type] || '/dashboard'
}
const kpiCards = computed(() => [
  { label:'今日到校', icon:'UsersRound', tone:'mint', value:data.value?.presentCount||0, suffix:`/ ${data.value?.studentCount||0} 人`, hint:`出勤率 ${attendanceRate.value}%`, to:'/attendance', emphasis:false },
  { label:'作业完成', icon:'NotebookPen', tone:'blue', value:data.value?.completedHomeworkCount||0, suffix:`/ ${data.value?.homeworkCount||0} 份`, hint:`${done.value}% 已完成`, to:'/homework', emphasis:false },
  { label:'待订正作业', icon:'BookOpenCheck', tone:'peach', value:data.value?.pendingCorrectionCount||0, suffix:'份', hint:'关注每一个知识盲点', to:'/homework?status=CORRECTION', emphasis:(data.value?.pendingCorrectionCount||0)>0 },
  isParent.value
    ? { label:'今日消耗课时', icon:'ClipboardCheck', tone:'lavender', value:data.value?.todayConsumed||0, suffix:'课时', hint:'查看课时账本', to:'/ledger', emphasis:false }
    : { label:'待发布小结', icon:'ClipboardCheck', tone:'lavender', value:data.value?.pendingSummaryCount||0, suffix:'份', hint:'发布后家长即可查看', to:'/summaries', emphasis:(data.value?.pendingSummaryCount||0)>0 },
])
</script>
<template><header class="page-heading dashboard-heading"><div><div class="eyebrow">EVERY LITTLE STEP MATTERS</div><h1>今日概览<span class="title-dot">.</span></h1><p>{{ greeting }}，{{ user?.name }}。每一个用心陪伴的日子，都在悄悄收获成长。</p></div><RouterLink :to="isParent ? '/summaries' : '/attendance'" class="btn primary"><AppIcon :name="isParent ? 'ClipboardList' : 'ScanLine'" :size="17" />{{ isParent ? '查看成长小结' : '学生到校签到' }}<AppIcon name="ArrowUpRight" :size="16" /></RouterLink></header>
<LoadState :loading="loading" :error="error" @retry="refresh"><template v-if="data">
  <RouterLink v-if="isAdmin" to="/campus-reports" class="btn secondary" style="margin-bottom:20px"><AppIcon name="Building2" :size="18" />校区总结与班级点评<AppIcon name="ArrowRight" :size="16" /></RouterLink><div class="dashboard-welcome"><div class="welcome-copy"><span class="tagline"><span></span> 陪伴，是最好的教育</span><h2>把每一天的小进步，<br />连成成长的大风景。</h2><p>教学有序，管理有方，陪伴更有温度。</p><RouterLink :to="isParent ? '/homework' : '/summaries'" class="welcome-link">{{ isParent ? '关注孩子的今日学习' : '记录今天的成长故事' }}<AppIcon name="ArrowRight" :size="17" /></RouterLink></div><div class="welcome-art" aria-hidden="true"><div class="art-orbit"></div><span class="art-spark s1"><AppIcon name="Sparkles" :size="23" /></span><span class="art-spark s2"><AppIcon name="Sparkles" :size="29" :stroke-width="1" /></span><div class="book-back"></div><div class="book-cover"><span>GROW<br />A LITTLE<br /><b>EVERY DAY.</b></span><AppIcon name="Sprout" :size="47" :stroke-width="1.3" /></div><div class="art-note"><AppIcon name="CircleCheck" :size="20" /><span>每一份努力，都被看见</span></div><span class="art-leaf"><AppIcon name="Leaf" :size="56" :stroke-width="1.2" /></span></div><div class="welcome-side"><AppIcon name="Sun" :size="24" /><span>今日陪伴</span><strong>{{ data.studentCount }}<small>位同学</small></strong><i></i><span>一起向上生长</span></div></div>
  <RouterLink to="/family-services" class="info-banner"><AppIcon name="HeartHandshake" :size="20" /><span>{{isParent?'课程余额预警、续费意向与今日订餐':'查看家长续费意向与各班订餐情况'}}<template v-if="data.lowBalanceCount"> · {{data.lowBalanceCount}} 位学生课时余额需关注</template></span><AppIcon name="ChevronRight" :size="17" /></RouterLink><section class="kpi-grid"><RouterLink v-for="card in kpiCards" :key="card.label" :to="card.to" class="kpi-card kpi-link"><div class="kpi-top"><span>{{ card.label }}</span><span class="kpi-icon" :class="card.tone"><AppIcon :name="card.icon" :size="21" /></span></div><div class="kpi-number">{{ card.value }}<small>{{ card.suffix }}</small></div><div class="kpi-bottom"><span class="kpi-hint"><i class="orange-dot" v-if="card.emphasis"></i>{{ card.hint }}</span><span class="kpi-go">查看<AppIcon name="ArrowUpRight" :size="17" /></span></div></RouterLink></section>
  <div class="dashboard-grid"><section class="panel progress-panel"><div class="panel-header"><div><h2>今日教学进度 <span class="section-caption">LEARNING PROGRESS</span></h2><p>每一科的认真，都值得被记录</p></div><RouterLink to="/homework" class="subtle-link">作业管理<AppIcon name="ArrowUpRight" :size="15" /></RouterLink></div><div class="subject-grid"><article v-for="(subject,index) in data.subjectProgress" :key="subject.subject" class="subject-card" :class="`subject-${index}`"><div class="subject-top"><span class="subject-icon"><AppIcon :name="['BookOpen','Sigma','Languages'][index % 3]!" :size="21" /></span><span>{{ subject.subject }}</span><span class="subject-percent">{{ percent(subject.completed,subject.total) }}<small>%</small></span></div><div class="subject-line"><i :style="{width:`${percent(subject.completed,subject.total)}%`}"></i></div><div class="subject-meta"><span>已完成 <strong>{{ subject.completed }}</strong> / {{ subject.total }} 份</span><span>{{ subject.total - subject.completed }} 份待完成</span></div></article><p v-if="!data.subjectProgress.length" class="muted">今日尚未布置作业，开始记录孩子们的进步吧。</p></div><div class="teaching-note"><AppIcon name="Lightbulb" :size="16" /><span>每一次及时反馈，都让学习更进一步。</span><RouterLink :to="isParent ? '/mistakes' : '/homework'">{{ isParent ? '查看错题' : '去批阅作业' }}<AppIcon name="ChevronRight" :size="14" /></RouterLink></div></section>
  <section class="panel tasks-panel"><div class="panel-header"><h2>待办事项 <span class="count-pill">{{ (data.pendingCorrectionCount ? 1 : 0) + (data.pendingSummaryCount ? 1 : 0) + (!isParent && data.lowBalanceCount ? 1 : 0) }}</span></h2><AppIcon name="ListTodo" :size="19" class="muted" /></div><RouterLink to="/homework?status=CORRECTION" class="task-item"><span class="task-check orange"><AppIcon name="NotebookPen" :size="17" /></span><div><strong>跟进作业订正</strong><small>{{ data.pendingCorrectionCount }} 份作业需要关注</small></div><AppIcon name="ChevronRight" :size="16" /></RouterLink><RouterLink to="/summaries" class="task-item"><span class="task-check green"><AppIcon name="FilePenLine" :size="17" /></span><div><strong>{{ isParent ? (data.pendingSummaryCount ? '等待老师发布小结' : '阅读今日成长小结') : '发布今日成长小结' }}</strong><small>{{ isParent && !data.pendingSummaryCount ? '今日小结已发布，点击查看' : `${data.pendingSummaryCount} 份小结${isParent ? '待老师发布' : '待完成'}` }}</small></div><AppIcon name="ChevronRight" :size="16" /></RouterLink><RouterLink v-if="!isParent" to="/ledger" class="task-item"><span class="task-check purple"><AppIcon name="WalletCards" :size="17" /></span><div><strong>关注课时余额</strong><small>{{ data.lowBalanceCount }} 位学生接近预警线</small></div><AppIcon name="ChevronRight" :size="16" /></RouterLink><div class="task-footer"><AppIcon name="Coffee" :size="16" /><span>有条不紊，留点时间给自己</span></div></section>
  <section class="panel student-panel"><div class="panel-header"><div><h2>{{ isParent ? '孩子的今日状态' : '学生今日状态' }} <span class="count-pill">{{ data.students.length }}</span></h2><p>从到校那一刻，关心就已开始</p></div><RouterLink to="/students" class="subtle-link">全部学生<AppIcon name="ArrowUpRight" :size="15" /></RouterLink></div><div class="table-wrap"><table><thead><tr><th>学生 / 班级</th><th>到校状态</th><th>签到时间</th><th>作业进度</th><th></th></tr></thead><tbody><tr v-for="(student,index) in data.students.slice(0,5)" :key="student.id"><td><div class="person"><StudentAvatar :student="student" /><span><strong>{{ student.name }}</strong><small>{{ student.campusName }} · {{ student.className }}</small></span></div></td><td><StatusBadge :value="student.attendanceStatus" /></td><td class="numeric">{{ time(student.checkInTime) }}</td><td><div class="table-progress"><div><i :style="{width:`${percent(student.homeworkCompleted,student.homeworkTotal)}%`}"></i></div><span>{{ student.homeworkCompleted }}/{{ student.homeworkTotal }}</span></div></td><td><RouterLink :to="`/students?studentId=${student.id}`" class="text-btn">详情</RouterLink></td></tr></tbody></table><div v-if="!data.students.length" class="compact-empty">今日暂无学生记录</div></div><div class="table-footer"><span>展示 {{ Math.min(5,data.students.length) }} / {{ data.students.length }} 位学生</span><RouterLink to="/students">查看完整名单<AppIcon name="ArrowRight" :size="14" /></RouterLink></div></section>
  <section class="panel attendance-panel"><div class="panel-header"><div><h2>每周出勤</h2><p>规律的陪伴，稳稳的成长</p></div><RouterLink to="/attendance" class="subtle-link">签到管理<AppIcon name="ArrowUpRight" :size="15" /></RouterLink><span class="chart-legend"><i></i>到校人数</span></div><div v-if="data.weeklyAttendance.length" class="attendance-chart"><div class="chart-y"><span>{{ Math.max(...data.weeklyAttendance.map(d => d.total),1) }}</span><span>{{ Math.round(Math.max(...data.weeklyAttendance.map(d => d.total),1) / 2) }}</span><span>0</span></div><div class="chart-columns"><div v-for="day in data.weeklyAttendance" :key="day.date" class="chart-column" :class="{today: day.date === data.date}"><div class="bar-track"><div class="bar" :style="{height:`${percent(day.present,Math.max(...data.weeklyAttendance.map(d => d.total),1))}%`}"><span>{{ day.present }} 人</span></div></div><span>{{ day.label }}</span><i v-if="day.date === data.date"></i></div></div></div><p v-else class="compact-empty">暂无本周考勤数据</p><div class="chart-footer"><span>今日到校率</span><strong>{{ attendanceRate }}<small>%</small></strong><span class="mini-pill">持续关注每一位同学</span></div></section>
  <section class="panel activities-panel"><div class="panel-header"><h2>校园动态 <span class="section-caption">CAMPUS MOMENTS</span></h2><RouterLink to="/mistakes" class="subtle-link">错题本<AppIcon name="ArrowUpRight" :size="15" /></RouterLink></div><div class="activity-list"><RouterLink v-for="(activity,index) in data.activities.slice(0,4)" :key="activity.id" :to="activityTarget(activity)" class="activity"><span class="activity-dot" :class="`activity-${index % 3}`"><AppIcon :name="['Check','BookOpen','Award'][index % 3]!" :size="15" /></span><div><strong>{{ activity.title }}</strong><p>{{ activity.detail }}</p></div><time>{{ time(activity.time) }}</time></RouterLink><p v-if="!data.activities.length" class="compact-empty">今天的成长故事，等待你来书写。</p></div></section></div>
</template></LoadState></template>
